open_atomic_invariant!(self.inv.borrow() => v => {
    let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
    res = self.pending.compare_exchange(Tracked(&mut pend_perm), 0, 1);

    proof {
        if res.is_ok() {
            // Transition from Empty(gva) to Offering(au)
            // pend was 0, now 1
            let tracked gva = proto.take_empty();
            let tracked au_inner = maybe_au.tracked_take();
            // Update gv from None to Some(au_inner)
            gva.update(&mut gv, Some(au_inner));
            // Store au_inner in the protocol
            proto = Offering(Tracked(au_inner));
            // Save gva for later use
            auth_au = Some(gva);
        }
        v = (value_perm, pend_perm, auth, gv, proto);
    }
});

if res.is_err() {
    return Some(Tracked(maybe_au.tracked_take()));
}

assert(auth_au is Some);

let res;

open_atomic_invariant!(self.inv.borrow() => v => {
    let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
    res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 0);

    proof {
        if res.is_ok() {
            // CAS 1->0 succeeded: our offer wasn't accepted, take it back
            let tracked au_offer = proto.take_offer();
            let tracked mut gva = auth_au.tracked_take();
            gva.update(&mut gv, None);
            proto = Empty(gva);
            maybe_au = Some(au_offer.get());
        }
        v = (value_perm, pend_perm, auth, gv, proto);
    }
});

if res.is_err() {
    open_atomic_invariant!(self.inv.borrow() => v => {
        let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
        self.pending.store(Tracked(&mut pend_perm), 0);

        proof {
            // pend was 2 (Accepted), transition to Empty
            // Use auth_au to update gv back to None
            let tracked mut gva = auth_au.tracked_take();
            gva.agree(&gv);
            // gv@->0.resolves() from Accepted invariant
            // auth_au@ == gv@ == Some(au) where au.resolves()
            // This means original au.resolves()
            gva.update(&mut gv, None);
            proto = Empty(gva);
            v = (value_perm, pend_perm, auth, gv, proto);
        }
    });

    return None;
}

